export class EntityKey {
  private readonly value: string;
  constructor(value: string) {
    if (typeof value !== "string" || !value.trim()) throw new TypeError("key must be nonblank");
    this.value = value;
  }
  toString(): string { return this.value; }
}

export interface NoteSnapshot { key: EntityKey; body: string; revision: number }
export type RevisionValue = string | number | boolean | null;
export interface DomainRecord { readonly occurredAt: number; getEntityKey(): EntityKey }

export class NoteRevisedRecord implements DomainRecord {
  readonly occurredAt: number;
  readonly note: Readonly<NoteSnapshot>;
  readonly changes: Readonly<Record<string, RevisionValue>>;

  constructor(occurredAt: number, note: NoteSnapshot, changes: Readonly<Record<string, RevisionValue>>) {
    if (!Number.isFinite(occurredAt) || occurredAt < 0) throw new RangeError("invalid occurrence value");
    if (typeof note.body !== "string") throw new TypeError("body must be a string");
    if (!Number.isInteger(note.revision) || note.revision < 0) throw new RangeError("invalid revision");
    const entries = Object.entries(changes);
    if (entries.length === 0) throw new TypeError("changes must not be empty");
    if (entries.some(([key]) => !key.trim())) throw new TypeError("change keys must be nonblank");
    this.occurredAt = occurredAt;
    this.note = Object.freeze({ ...note });
    this.changes = changes;
  }

  getEntityKey(): EntityKey { return this.note.key; }
}

