import { EntityKey, NoteRevisedRecord } from './solution';
import type { NoteSnapshot, RevisionValue } from './solution';

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function throws(fn: () => unknown, ctor: Function, message: string): void {
  try { fn(); } catch (error) {
    if (error instanceof (ctor as any)) return;
    throw new Error(`${message}: wrong error type`);
  }
  throw new Error(`${message}: did not throw`);
}

throws(() => new EntityKey(''), TypeError, 'empty key');
throws(() => new EntityKey(' \t '), TypeError, 'whitespace key');
const key = new EntityKey('note-1');
equal(key.toString(), 'note-1', 'key string');

const note: NoteSnapshot = { key, body: 'before', revision: 2 };
const changes: Record<string, RevisionValue> = {};
changes.body = 'after';
changes.reviewed = true;
changes.count = 3;
changes.optional = null;
const event = new NoteRevisedRecord(42.5, note, changes);
equal(event.occurredAt, 42.5, 'occurredAt');
assert(event.getEntityKey() === key, 'returns note key');
assert(event.note !== note, 'note snapshot copied');
assert(event.changes !== changes, 'changes map copied');
assert(Object.isFrozen(event.note), 'note snapshot frozen');
assert(Object.isFrozen(event.changes), 'changes map frozen');
equal(Object.keys(event.changes).join(','), 'body,reviewed,count,optional', 'change insertion order');

note.body = 'caller changed';
note.revision = 99;
changes.body = 'caller changed';
changes.extra = 'new';
equal(event.note.body, 'before', 'note mutation isolated');
equal(event.note.revision, 2, 'revision mutation isolated');
equal(event.changes.body, 'after', 'change mutation isolated');
assert(!Object.prototype.hasOwnProperty.call(event.changes, 'extra'), 'later change key isolated');

new NoteRevisedRecord(0, { key, body: '', revision: 0 }, { x: false });
for (const occurredAt of [-1, Infinity, -Infinity, NaN]) {
  throws(() => new NoteRevisedRecord(occurredAt, { key, body: 'x', revision: 0 }, { x: 1 }), RangeError, 'invalid occurredAt');
}
for (const revision of [-1, 1.5, Infinity, NaN]) {
  throws(() => new NoteRevisedRecord(0, { key, body: 'x', revision }, { x: 1 }), RangeError, 'invalid revision');
}
throws(() => new NoteRevisedRecord(0, { key, body: 3 as unknown as string, revision: 0 }, { x: 1 }), TypeError, 'non-string body');
throws(() => new NoteRevisedRecord(0, { key, body: 'x', revision: 0 }, {}), TypeError, 'changes required');
throws(() => new NoteRevisedRecord(0, { key, body: 'x', revision: 0 }, { '  ': 1 }), TypeError, 'blank change key');

